exercises.solution:
def add(records, crop, kg):
    crop = str(crop).strip().lower()
    if not crop or isinstance(kg, bool) or not isinstance(kg, (int, float)) or kg <= 0:
        raise ValueError("bad record")
    records.append({"crop": crop, "kg": kg})


def totals(records):
    t = {}
    for r in records:
        t[r["crop"]] = t.get(r["crop"], 0) + r["kg"]
    return t


def top(records, n):
    return sorted(totals(records).items(), key=lambda p: p[1], reverse=True)[:n]


def save(records, path):
    with open(path, "w", encoding="utf-8") as f:
        for r in records:
            f.write(f"{r['crop']},{r['kg']}\n")


def load(path):
    try:
        with open(path, encoding="utf-8") as f:
            out = []
            for line in f:
                if line.strip():
                    crop, kg = line.strip().rsplit(",", 1)
                    kg = float(kg)
                    out.append({"crop": crop, "kg": int(kg) if kg.is_integer() else kg})
            return out
    except FileNotFoundError:
        return []
